def draw(paths):
    base_pen = TTGlyphPen(None)
    pen = Cu2QuPen(TransformPen(base_pen, Transform(1, 0, 0, -1, 0, UNITS)), 1.0)
    for path in paths:
        parse_path(path, pen)
    return base_pen.glyph()


def main():
    glyph_order = [".notdef"] + list(ICONS.keys())
    cmap = {code: name for name, (code, _) in ICONS.items()}
    glyphs = {".notdef": TTGlyphPen(None).glyph()}
    glyphs.update({name: draw(paths) for name, (_, paths) in ICONS.items()})
    metrics = {name: (UNITS, 0) for name in glyph_order}

    fb = FontBuilder(UNITS, isTTF=True)
    fb.setupGlyphOrder(glyph_order)
    fb.setupCharacterMap(cmap)
    fb.setupGlyf(glyphs)
    fb.setupHorizontalMetrics(metrics)
    fb.setupHorizontalHeader(ascent=960, descent=-64)
    fb.setupOS2(sTypoAscender=960, sTypoDescender=-64, usWinAscent=960, usWinDescent=64)
    fb.setupNameTable({
        "familyName": "FoodRadarIconfont",
        "styleName": "Regular",
        "uniqueFontIdentifier": "FoodRadarIconfont Regular",
        "fullName": "FoodRadarIconfont Regular",
        "psName": "FoodRadarIconfont-Regular",
    })
    fb.setupPost()
    fb.save("iconfont.ttf")


if __name__ == "__main__":
    main()
